from collections import deque

def shortest_path(graph, source, target):
    # If the source or target is not in the graph, the path is unreachable
    if source not in graph or target not in graph:
        return float("inf"), None

    # Initialize distances and predecessor dictionary
    distances = {node: float("inf") for node in graph}
    distances[source] = 0
    predecessor = {node: None for node in graph}

    # Using a queue for BFS
    queue = deque([source])

    while queue:
        current = queue.popleft()
        for neighbour, weight in graph[current]:
            distance_through_current = distances[current] + weight
            if distance_through_current < distances[neighbour]:
                distances[neighbour] = distance_through_current
                predecessor[neighbour] = current
                # Enqueue the neighbour
                queue.append(neighbour)

    # If the target is not reachable, distances[target] will still be infinity
    if distances[target] == float("inf"):
        return float("inf"), None

    # Reconstruct the path from target to source
    path = deque()
    current = target
    while current is not None:
        path.appendleft(current)
        current = predecessor[current]

    return distances[target], list(path)

