def shortest_path(graph, source, target):
    # Implementing Dijkstra's algorithm
    from heapq import heappush, heappop
    import math

    # Priority queue to store (distance, node) pairs, initialized with (0, source)
    queue = [(0, source)]
    # Tracking dictionary to store the shortest distance from the source to a node
    distances = {node: math.inf for node in graph}
    distances[source] = 0
    # Tracking dictionary to store the path to a node
    paths = {source: []}

    while queue:
        current_distance, current_node = heappop(queue)

        if current_node == target:
            # Reconstruct the path from target to source
            path = [target]
            while path[-1] != source:
                path.append(paths[path[-1]].pop())
            path.reverse()
            return (current_distance, path)

        for neighbor, weight in graph.get(current_node, []):
            distance = current_distance + weight

            if distance < distances[neighbor]:
                heappush(queue, (distance, neighbor))
                distances[neighbor] = distance
                paths[neighbor] = paths[current_node] + [neighbor]

    # If the target is unreachable
    return (math.inf, None)

