    visited = set()

    while queue:
        (cost, current, path) = heappop(queue)

        if current in visited:
            continue
        visited.add(current)

        # Add current node to the path
        path = path + [current]

        # If target is reached, return the distance and the path
        if current == target:
            return (cost, path)

        for (neighbor, weight) in graph.get(current, []):
