            new_cost = cost + weight
            if neighbor not in distances or new_cost < distances[neighbor][0]:
                distances[neighbor] = (new_cost, path + [neighbor])
                heappush(queue, (new_cost, neighbor, path + [neighbor]))

    # If the target is unreachable, return infinity and None
    return (float("inf"), None)
