import heapq

def shortest_path(graph, source, target):
    # Initialize the priority queue with the source node, distance 0, and path containing only the source node
    priority_queue = [(0, source, [source])]
    visited = set()

    while priority_queue:
        # Dequeue the node with the smallest distance
        current_distance, current_node, current_path = heapq.heappop(priority_queue)

        # If we have reached the target, return the path and distance
        if current_node == target:
            return (current_distance, current_path)

        # If the current node is not visited
        if current_node not in visited:
            visited.add(current_node)

            # Iterate over the neighbors of the current node
            for neighbor, weight in graph.get(current_node, []):
                if neighbor not in visited:
                    # Calculate the tentative distance to the neighbor via the current node
                    tentative_distance = current_distance + weight
                    # If it's the first time we're visiting the neighbor or the new distance is shorter, update the path
                    if (neighbor, tentative_distance, current_path + [neighbor]) not in visited:
                        heapq.heappush(priority_queue, (tentative_distance, neighbor, current_path + [neighbor]))

    # If the target is unreachable, return infinity and None
    return (float("inf"), None)

